/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600, tracking-tight. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

const isBrand = (label: string) => label.trim().toLowerCase() === "remocn";

interface DonutSegment {
  label: string;
  value: number;
}

interface ShareDonutProps {
  segments?: DonutSegment[];
  highlight?: number;
  accent?: string;
  /** Color of the percentages and the center figure; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the labels. Load it yourself; DM Sans by default. */
  fontFamily?: string;
  /** Frames for the ring to draw all the way round. */
  drawLength?: number;
  /** Ring thickness, in px at 720p. */
  thickness?: number;
  /** Replaces the remocn mark wherever a slice is labelled "remocn". */
  logo?: React.ReactNode;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Size of the donut and labels, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

const DEFAULT_SEGMENTS: DonutSegment[] = [
  { label: "remocn", value: 38 },
  { label: "Kitebase", value: 24 },
  { label: "Lumen", value: 17 },
  { label: "Fernway", value: 12 },
  { label: "Other", value: 9 },
];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_SEG = Easing.bezier(0.55, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.22)",
    track: "rgba(255,255,255,0.05)",
    grays: ["#B9B7B2", "#85848A", "#5C5B61", "#3E3D43"],
    // gradients.sh "halo": the highlighted share burns accent → rose → amber.
    halo: ["#E2457A", "#FFB36B"],
    haze: ["rgba(226,69,122,0.12)", "rgba(61,77,255,0.09)"],
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.22)",
    track: "rgba(18,18,20,0.05)",
    grays: ["#4F4D49", "#85837E", "#AEACA6", "#D0CEC8"],
    halo: ["#E2457A", "#FF9A4D"],
    haze: ["rgba(226,69,122,0.08)", "rgba(61,77,255,0.05)"],
    grain: 0.045,
  },
} as const;

const DRAW_START = 6;
const DRAW_LEN = 52;
const TAU = Math.PI * 2;

function pt(cx: number, cy: number, r: number, a: number) {
  return { x: cx + r * Math.sin(a), y: cy - r * Math.cos(a) };
}

function arc(cx: number, cy: number, r: number, a0: number, a1: number) {
  const s = pt(cx, cy, r, a0);
  const e = pt(cx, cy, r, a1);
  const large = a1 - a0 > Math.PI ? 1 : 0;
  return `M ${s.x.toFixed(2)} ${s.y.toFixed(2)} A ${r} ${r} 0 ${large} 1 ${e.x.toFixed(2)} ${e.y.toFixed(2)}`;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={29}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function ShareDonutBase({
  segments = DEFAULT_SEGMENTS,
  highlight = 0,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  drawLength = DRAW_LEN,
  thickness = 12,
  logo,
  grain = true,
  scale: size = 1,
  delay = 0,
  theme = "dark",
  speed = 1,
}: ShareDonutProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps } = useSceneConfig();
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const fill =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const list = segments.slice(0, 5);
  const hl = Math.min(Math.max(0, Math.round(highlight)), list.length - 1);
  const total = list.reduce((s, x) => s + Math.max(0, x.value), 0) || 1;

  const cx = width / 2;
  const cy = height / 2;
  const R = height * 0.3;
  const sw = thickness * u;
  const gapA = (6 * u) / R;

  let acc = 0;
  let grayIdx = 0;
  let clock = DRAW_START;
  const segs = list.map((s, i) => {
    const frac = Math.max(0, s.value) / total;
    const a0 = acc * TAU;
    acc += frac;
    const a1 = acc * TAU;
    const dur = Math.max(9, drawLength * frac);
    const start = clock;
    clock += dur - 2;
    const color = i === hl ? accent : p.grays[Math.min(grayIdx++, 3)];
    return {
      ...s,
      i,
      frac,
      a0: a0 + gapA / 2,
      a1: a1 - gapA / 2,
      mid: (a0 + a1) / 2,
      start,
      end: start + dur,
      color,
      pct: Math.round(frac * 100),
    };
  });
  const drawEnd = segs.length ? segs[segs.length - 1].end : DRAW_START;
  const HIT = drawEnd + 8;

  const detach = spring({
    frame: t - HIT,
    fps,
    config: { damping: 15, stiffness: 150, mass: 0.7 },
  });
  const dim = interpolate(t, [HIT, HIT + 16], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const land = interpolate(t, [HIT + 4, HIT + 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const count = interpolate(t, [HIT + 4, HIT + 30], [0.55, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  const labIn = interpolate(t, [HIT + 12, HIT + 30], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const stage = interpolate(t, [0, 10], [0.4, 1], CLAMP);
  const spin = interpolate(t, [0, HIT + 10], [-14, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const push = interpolate(t, [0, HIT + 60], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const scale = 0.97 + 0.04 * push;

  const target = segs[hl];
  const gradId = `h${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const g0 = target ? pt(cx, cy, R, target.a0) : { x: cx, y: cy - R };
  const g1 = target ? pt(cx, cy, R, target.a1) : { x: cx + R, y: cy };
  const off = detach * 18 * u;
  const hx = target ? Math.sin(target.mid) * off : 0;
  const hy = target ? -Math.cos(target.mid) * off : 0;

  return (
    <AbsoluteFill style={{ background: fill, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 50%, transparent ${R * 0.62}px, ${p.haze[0]} ${R * 1.02}px, ${p.haze[1]} ${R * 1.3}px, transparent ${R * 1.85}px)`,
          opacity: 0.25 + 0.75 * land,
          transform: `rotate(${spin}deg)`,
        }}
      />
      <ScaleLayer scale={size}>
        <AbsoluteFill
          style={{
            // The push outlasts every other move, so this one tilt covers the
            // labels and the center figure too.
            transform: `scale(${scale})${glide(push > 0 && push < 1)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0, opacity: stage }}
            aria-hidden
          >
            <defs>
              <linearGradient
                id={gradId}
                gradientUnits="userSpaceOnUse"
                x1={g0.x}
                y1={g0.y}
                x2={g1.x}
                y2={g1.y}
              >
                <stop offset="0" stopColor={accent} />
                <stop offset="0.58" stopColor={p.halo[0]} />
                <stop offset="1" stopColor={p.halo[1]} />
              </linearGradient>
            </defs>
            <g transform={`rotate(${spin} ${cx} ${cy})`}>
              <circle
                cx={cx}
                cy={cy}
                r={R}
                fill="none"
                stroke={p.track}
                strokeWidth={sw}
                opacity={1 - dim}
              />
              {segs.map((s) => {
                const k = interpolate(t, [s.start, s.end], [0, 1], {
                  ...CLAMP,
                  easing: EASE_SEG,
                });
                if (k <= 0 || s.a1 <= s.a0) return null;
                const isHl = s.i === hl;
                const a1 = s.a0 + (s.a1 - s.a0) * k;
                return (
                  <path
                    key={s.label}
                    d={arc(cx, cy, R, s.a0, a1)}
                    fill="none"
                    stroke={isHl ? `url(#${gradId})` : s.color}
                    strokeLinecap={isHl ? "round" : "butt"}
                    strokeWidth={isHl ? sw * (1 + 0.5 * detach) : sw}
                    opacity={isHl ? 1 : 1 - 0.5 * dim}
                    transform={isHl ? `translate(${hx} ${hy})` : undefined}
                  />
                );
              })}
              {segs.map((s) => {
                const a = interpolate(t, [s.end - 6, s.end + 8], [0, 1], {
                  ...CLAMP,
                  easing: EASE_OUT,
                });
                const p0 = pt(cx, cy, R + sw / 2 + 8 * u, s.mid);
                const p1 = pt(cx, cy, R + sw / 2 + 8 * u + 14 * u * a, s.mid);
                const fade = s.i === hl ? 1 - dim : 1 - 0.55 * dim;
                return (
                  <line
                    key={s.label}
                    x1={p0.x}
                    y1={p0.y}
                    x2={p1.x}
                    y2={p1.y}
                    stroke={p.hair}
                    strokeWidth={Math.max(1, u)}
                    opacity={a * fade}
                  />
                );
              })}
            </g>
          </svg>

          {segs.map((s) => {
            const a = interpolate(t, [s.end - 4, s.end + 12], [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
            const ang = s.mid + (spin * Math.PI) / 180;
            const q = pt(cx, cy, R + sw / 2 + 38 * u + (1 - a) * -8 * u, ang);
            // Placed by `left`/`top`, a label clicked along its orbit pixel by
            // pixel; layout holds where it lands and the travel is a transform.
            const rest = pt(cx, cy, R + sw / 2 + 38 * u, s.mid);
            const dx = q.x - rest.x;
            const dy = q.y - rest.y;
            const right = Math.sin(ang) >= -0.05;
            const fade = s.i === hl ? 1 - dim : 1 - 0.6 * dim;
            return (
              <div
                key={s.label}
                style={{
                  position: "absolute",
                  left: rest.x,
                  top: rest.y,
                  transform: `${dx || dy ? `translate(${dx}px, ${dy}px) ` : ""}translate(${right ? 0 : -100}%, -50%)`,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: right ? "flex-start" : "flex-end",
                  gap: 2 * u,
                  opacity: a * fade * stage,
                  whiteSpace: "nowrap",
                }}
              >
                <span
                  style={{
                    fontFamily,
                    fontWeight: 500,
                    fontSize: 22 * u,
                    letterSpacing: "-0.02em",
                    color: fg,
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  {s.pct}%
                </span>
                {isBrand(s.label) ? (
                  (logo ?? <RemocnLogo fontSize={15 * u} color={p.muted} />)
                ) : (
                  <span
                    style={{
                      fontFamily,
                      fontWeight: 400,
                      fontSize: 15 * u,
                      color: p.muted,
                    }}
                  >
                    {s.label}
                  </span>
                )}
              </div>
            );
          })}

          {target ? (
            <AbsoluteFill
              style={{
                alignItems: "center",
                justifyContent: "center",
                flexDirection: "column",
              }}
            >
              <div
                style={{
                  fontFamily: display,
                  fontWeight: 300,
                  fontSize: 176 * u,
                  lineHeight: 0.9,
                  letterSpacing: "-0.035em",
                  color: fg,
                  fontVariantNumeric: "tabular-nums",
                  whiteSpace: "nowrap",
                  opacity: land,
                  filter:
                    land < 0.99 ? `blur(${(1 - land) * 8 * u}px)` : undefined,
                  transform: `translateY(${(1 - land) * 22 * u}px) scale(${1.05 - 0.05 * land})`,
                  marginTop: 10 * u,
                }}
              >
                {Math.round(target.pct * count)}
                <span
                  style={{
                    fontSize: 92 * u,
                    fontStyle: "italic",
                    letterSpacing: "-0.02em",
                    marginLeft: 4 * u,
                    color: p.muted,
                  }}
                >
                  %
                </span>
              </div>
              <div
                style={{
                  marginTop: 14 * u,
                  display: "flex",
                  alignItems: "center",
                  gap: 10 * u,
                  opacity: labIn,
                  transform: `translateY(${(1 - labIn) * 8 * u}px)`,
                }}
              >
                {isBrand(target.label) ? (
                  (logo ?? <RemocnLogo fontSize={28 * u} color={fg} />)
                ) : (
                  <>
                    <span
                      style={{
                        width: 10 * u,
                        height: 10 * u,
                        borderRadius: "50%",
                        background: `linear-gradient(135deg, ${accent}, ${p.halo[0]}, ${p.halo[1]})`,
                      }}
                    />
                    <span
                      style={{
                        fontFamily,
                        fontWeight: 400,
                        fontSize: 22 * u,
                        letterSpacing: "-0.01em",
                        color: p.muted,
                        whiteSpace: "nowrap",
                      }}
                    >
                      {target.label}
                    </span>
                  </>
                )}
              </div>
            </AbsoluteFill>
          ) : null}
        </AbsoluteFill>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${fill} 100%)`,
          opacity: 0.6,
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  highlight: {
    type: "number",
    default: 0,
    min: 0,
    max: 10,
    step: 1,
    description: "Highlight",
    hiddenFromList: false,
  },
  drawLength: {
    type: "number",
    default: 52,
    min: 10,
    max: 120,
    step: 1,
    description: "Draw length (frames)",
    hiddenFromList: false,
  },
  thickness: {
    type: "number",
    default: 12,
    min: 2,
    max: 40,
    step: 1,
    description: "Ring thickness",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "DM Sans",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","highlight","drawLength","thickness","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  highlight: 0,
  drawLength: 52,
  thickness: 12,
  accent: "#3B5BFD",
  fontFamily: "DM Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ShareDonutElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShareDonutBase>;

const ShareDonutInner = forwardRef<
  HTMLDivElement,
  ShareDonutElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShareDonut>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShareDonutBase
          {...(componentProps as unknown as ComponentProps<typeof ShareDonutBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShareDonut = Interactive.withSchema({
  Component: ShareDonutInner,
  componentName: "<ShareDonut>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
